<?php
require_once "inc/config.php"; require_once "inc/admin_auth.php"; require_admin_permission($pdo,'complaints');
$status=(string)($_GET['status']??'');$where=[];$p=[];if(in_array($status,['new','reviewed','resolved'],true)){$where[]='lc.status=?';$p[]=$status;}
$sql="SELECT lc.*,l.title listing_title FROM listing_complaints lc LEFT JOIN listings l ON l.id=lc.listing_id";if($where)$sql.=" WHERE ".implode(' AND ',$where);$sql.=" ORDER BY lc.id DESC LIMIT 100";$stmt=$pdo->prepare($sql);$stmt->execute($p);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);$csrf=admin_csrf_token();
?>
<!doctype html><html lang="az"><head><?php include "inc/head.php"; ?></head><body><div class="app-main"><div id="app-wrapper" class="app-wrapper d-flex flex-column align-items-stretch min-vh-100"><?php include "inc/sidebar.php"; ?><?php include "inc/navbar.php"; ?><div class="app-content-wrapper py-13"><div class="container-fluid"><div class="page-header pb-7"><h2 class="fw-semibold fs-7">Şikayət və report mərkəzi</h2></div><form class="mb-5"><select class="form-control" name="status" onchange="this.form.submit()"><option value="">Bütün statuslar</option><?php foreach(['new','reviewed','resolved'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body table-responsive"><table class="table align-middle"><tr><th>ID</th><th>Elan</th><th>Şikayətçi</th><th>Mətn</th><th>Status</th><th>Əməliyyat</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=admin_h($r['listing_title']??'#'.$r['listing_id'])?></td><td><?=admin_h($r['full_name'])?><br><?=admin_h($r['email'])?></td><td style="max-width:420px"><?=admin_h($r['message'])?></td><td><?=admin_h($r['status'])?></td><td><form method="post" action="api/management/complaint_action.php" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-control form-control-sm"><option value="new">Yeni</option><option value="reviewed">Araşdırılır</option><option value="resolved">Həll edildi</option></select><button class="btn btn-sm btn-primary">Yadda saxla</button></form></td></tr><?php endforeach;?></table></div></div></div></div><?php include "inc/footer.php"; ?></div></div><?php include "inc/scripts_url.php"; ?></body></html>
